/// Supported actions represented in the assistant UI.
enum ActionIconKind {
  delete,
  press,
  parallel,
  image,
  terminal,
  read,
  summary,
  fast,
  search,
  retry,
  smart
}

/// Compact, theme-tinted vector for an assistant action.
/// Uses the path parser in [VectorIcon], with no additional dependency.
class ActionVectorIcon extends StatelessWidget {
  const ActionVectorIcon(
      {super.key, required this.kind, this.size = 18, this.color});

  final ActionIconKind kind;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) => VectorIcon(
        <String>[_pathFor(kind)],
        viewport: 960,
        size: size,
        color: color,
      );

  static String _pathFor(ActionIconKind kind) => switch (kind) {
        ActionIconKind.delete => ActionIconPathData.delete,
        ActionIconKind.press => ActionIconPathData.toolPressing,
        ActionIconKind.parallel => ActionIconPathData.parallelTools,
        ActionIconKind.image => ActionIconPathData.imageGeneration,
        ActionIconKind.terminal => ActionIconPathData.toolsUse,
        ActionIconKind.read => ActionIconPathData.readWeb,
        ActionIconKind.summary => ActionIconPathData.summaryWeb,
        ActionIconKind.fast => ActionIconPathData.fastResponse,
        ActionIconKind.search => ActionIconPathData.searchWeb,
        ActionIconKind.retry => ActionIconPathData.retry,
        ActionIconKind.smart => ActionIconPathData.smartTool,
      };
}
